# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift
from hourglass.parsing import parse_span
from hourglass.timesheet import timesheet_lines


def make_shift(worker, day, text):
    return Shift(worker, day, parse_span(text))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            make_shift("Ana", "mon", "09:00-10:00"),
            make_shift("Bo", "mon", "09:00-13:30"),
            make_shift("Bo", "tue", "09:00-10:00")
        ])
        self.assertEqual(lines, [
            "Bo: shifts 2, hours 5.5",
            "Ana: shifts 1, hours 1.0"
        ])

    def test_one_decimal_place(self):
        lines = timesheet_lines([
            make_shift("Ana", "mon", "09:00-09:20")
        ])
        self.assertEqual(lines, ["Ana: shifts 1, hours 0.3"])

    def test_tie_breaks_on_shifts_then_name(self):
        lines = timesheet_lines([
            make_shift("Zed", "mon", "09:00-11:00"),
            make_shift("Amy", "mon", "09:00-10:00"),
            make_shift("Amy", "tue", "09:00-10:00"),
            make_shift("Bea", "mon", "09:00-11:00")
        ])
        names = [line.split(":")[0] for line in lines]
        self.assertEqual(names, ["Amy", "Bea", "Zed"])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        for name in ("", "   "):
            shift = make_shift(name, "mon", "09:00-10:00")
            with self.assertRaises(ProjectError):
                timesheet_lines([shift])


if __name__ == "__main__":
    unittest.main()
